"""Runtime positive-convex-quad guard over the final native surface mesh.

The source geometry is not changed. Face-corner topology supplies the actual
four vertex positions, and explicit FACE statistics turn the result into
single values suitable for a Geometry Switch outside the backend.
"""
from .backend_runtime import V, rm


def _minimum(g, geometry, value, label):
    node = g.node('GeometryNodeAttributeStatistic', label)
    node.data_type = 'FLOAT'
    node.domain = 'FACE'
    g.bind(geometry, node.inputs['Geometry'])
    g.bind(value, node.inputs['Attribute'])
    return V(g, node.outputs['Min'])


def _and(g, a, b):
    node = g.node('FunctionNodeBooleanMath', 'Require both native mesh conditions')
    node.operation = 'AND'
    g.bind(a, node.inputs[0])
    g.bind(b, node.inputs[1])
    return V(g, node.outputs[0])


def check(g, geometry):
    """Return ``(valid, minimum_cross, all_quad)`` as single values.

    ``valid`` requires a nonempty face domain, exactly four corners per face,
    and positive XY cross products at all four corners. This rejects flipped,
    concave, self-crossed and degenerate quads. An empty mesh is invalid here;
    callers may explicitly permit an empty grass output when no separator
    exists. Chart correspondence, when supplied, must also pass its physical
    agreement check. This local shape guard does not certify manifold connectivity.
    """
    g.section('Guard actual generated quads before publishing geometry')
    face_index = V(g, g.node('GeometryNodeInputIndex', 'Current face index').outputs['Index'])
    corners = g.node('GeometryNodeCornersOfFace', 'Actual first corner and face size')
    g.bind(face_index, corners.inputs['Face Index'])
    corners.inputs['Sort Index'].default_value = 0
    points = []
    for i in range(4):
        offset = g.node('GeometryNodeOffsetCornerInFace', 'Actual face corner '+str(i))
        g.bind(corners.outputs['Corner Index'], offset.inputs['Corner Index'])
        offset.inputs['Offset'].default_value = i
        vertex = g.node('GeometryNodeVertexOfCorner', 'Vertex at face corner '+str(i))
        g.bind(offset.outputs['Corner Index'], vertex.inputs['Corner Index'])
        position = g.node('GeometryNodeFieldAtIndex', 'Position of actual face vertex '+str(i))
        position.data_type = 'FLOAT_VECTOR'
        position.domain = 'POINT'
        g.bind(vertex.outputs['Vertex Index'], position.inputs['Index'])
        g.bind(g.position(), position.inputs['Value'])
        points.append(g.separate(V(g, position.outputs['Value']))[:2])
    minimum = None
    for i in range(4):
        p, q, r = points[i], points[(i+1) % 4], points[(i+2) % 4]
        ex, ey = q[0]-p[0], q[1]-p[1]
        fx, fy = r[0]-q[0], r[1]-q[1]
        cross = ex*fy-ey*fx
        minimum = cross if minimum is None else g.math('MINIMUM', minimum, cross)
    minimum_cross = _minimum(g, geometry, minimum, 'Smallest corner cross on final mesh')
    quad_fraction = _minimum(g, geometry, rm.equal(g, V(g, corners.outputs['Total']), 4.),
                             'Require four actual corners on every face')
    all_quad = g.math('GREATER_THAN', quad_fraction, .5)
    size = g.node('GeometryNodeAttributeDomainSize', 'Require a nonempty pavement mesh')
    size.component = 'MESH'
    g.bind(geometry, size.inputs['Geometry'])
    nonempty = g.math('GREATER_THAN', V(g, size.outputs['Face Count']), 0.)
    valid = _and(g, nonempty, _and(g, all_quad,
                                 g.math('GREATER_THAN', minimum_cross, 0.)))
    seam = g.node('GeometryNodeInputNamedAttribute', 'Verified chart correspondence when present')
    seam.data_type = 'BOOLEAN'; seam.inputs['Name'].default_value = '_chart_seam_ok'
    seam_field = g.math('MAXIMUM', 1.-V(g, seam.outputs['Exists']), V(g, seam.outputs['Attribute']))
    seam_ok = _minimum(g, geometry, seam_field, 'Require physically matching chart seams')
    valid = _and(g, valid, g.math('GREATER_THAN', seam_ok, .5))
    return valid, minimum_cross, all_quad
